This Needleman-Wunsch implementation gives suspiciously high scores. The first row and column of the DP matrix were initialized to zero, which silently turns it into a semi-global aligner:

def nw(a, b, match=1, mismatch=-1, gap=-1):
    m, n = len(a), len(b)
    F = [[0]*(n+1) for _ in range(m+1)]
    for i in range(1, m+1):
        for j in range(1, n+1):
            d = F[i-1][j-1] + (match if a[i-1]==b[j-1] else mismatch)
            F[i][j] = max(d, F[i-1][j] + gap, F[i][j-1] + gap)
    return F[m][n]

